
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_kt1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_kt1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.424659795928474e+00, -4.345434209757571e+00, -4.234711709884881e+00, -4.081954571553284e+00, -3.875139888584767e+00, -3.602798355183782e+00, -3.258703949201771e+00, -2.850533676580696e+00, -2.411210087659244e+00, -1.984985284909573e+00, -1.405415982105888e+00, -7.170901440055771e-01, -6.034563748202294e-01, -4.933825166831255e-01, -3.362171503695393e-01, -1.869676119158616e-01, -8.386743288295315e-02, -2.796146027935595e-02, -5.998680127596015e-03, -6.741775166214280e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


